<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$id=$_GET['id']??'';$s=$pdo->prepare("SELECT a.*,u.username,u.display_name,s.title,s.canonical_url,s.status source_status,c.selected_text,c.start_seconds,c.end_seconds,c.screenshot_target_path FROM annotations a JOIN users u ON u.id=a.user_id JOIN sources s ON s.id=a.source_id JOIN captures c ON c.id=a.capture_id WHERE a.public_id=? AND a.visibility='public' AND a.status='published'");$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Annotation not found.');}
?><!doctype html><html><head><meta charset="utf-8"><title><?=h($a['title']?:'Annotation')?> · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a></header><main class="panel article"><div class="meta"><?=h($a['display_name'])?> · @<?=h($a['username'])?></div><?php if($a['source_status']==='edited'):?><div class="badge warn">Source changed after this annotation</div><?php endif?><h1><?=h($a['text_commentary']?:'Annotation')?></h1><?php if($a['selected_text']):?><blockquote><?=h($a['selected_text'])?></blockquote><?php endif?><p><a href="<?=h($a['canonical_url'])?>" target="_blank" rel="noopener">View original source ↗</a></p><div class="actions"><a class="button secondary" href="/file-a-claim.php?id=<?=h($a['public_id'])?>">File a claim</a></div></main></body></html>
